//   类型 2（把 P 换成 P^{-1}）：逆的逆就是自己，所以只需把两份交换一下（O(1)）。
//   类型 1（交换 P_x, P_y）：只动当前 P 的两个位置，逆表同步改两格即可。
#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<int> P(N + 1), I(N + 1);        // P = 排列；I = P 的逆（I[P_i] = i）
    for (int i = 1; i <= N; i++) {
        cin >> P[i];
        I[P[i]] = i;
    }

    // pp 指向「当前排列」，qq 指向「当前排列的逆」；类型 2 时两个指针互换。
    vector<int> *pp = &P, *qq = &I;

    while (Q--) {
        int typ;
        cin >> typ;
        if (typ == 1) {
            int x, y;
            cin >> x >> y;
            swap((*pp)[x], (*pp)[y]);
            // 交换后逆表只需在这两个值上改指向
            (*qq)[(*pp)[x]] = x;
            (*qq)[(*pp)[y]] = y;
        } else {
            swap(pp, qq);                  // P <- P^{-1}，同时新的逆就是旧 P
        }
    }

    string out;
    out.reserve((size_t)N * 8);
    for (int i = 1; i <= N; i++) {
        out += to_string((*pp)[i]);
        out += (i == N ? '\n' : ' ');
    }
    cout << out;
    return 0;
