    int mid = (l + r) >> 1;
    if (pos <= mid) update(o << 1, l, mid, pos, v);
    else            update(o << 1 | 1, mid + 1, r, pos, v);
    pull(o);
}

// 区间查询 [ql,qr] 的最小值（含位置）与最大值（含位置），结果累加进引用参数
void query(int o, int l, int r, int ql, int qr,
           int &rmn, int &rmnp, int &rmx, int &rmxp) {
    if (ql <= l && r <= qr) {     // 整段被覆盖：直接拿这一段的答案去更新全局答案
        if (mn[o] < rmn) { rmn = mn[o]; rmnp = mnp[o]; }
        if (mx[o] > rmx) { rmx = mx[o]; rmxp = mxp[o]; }
        return;
    }
    int mid = (l + r) >> 1;
    if (ql <= mid) query(o << 1, l, mid, ql, qr, rmn, rmnp, rmx, rmxp);
    if (qr > mid)  query(o << 1 | 1, mid + 1, r, ql, qr, rmn, rmnp, rmx, rmxp);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> m;
    val.assign(n + 1, 0);
    for (int i = 1; i <= n; i++) cin >> val[i];

    mn.assign(4 * n + 4, INF);
    mx.assign(4 * n + 4, -INF);
    mnp.assign(4 * n + 4, 0);
    mxp.assign(4 * n + 4, 0);
    build(1, 1, n);

    for (int q = 0; q < m; q++) {
        int L, R;
        cin >> L >> R;
        int rmn = INF, rmnp = -1, rmx = -INF, rmxp = -1;
        query(1, 1, n, L, R, rmn, rmnp, rmx, rmxp);
        // 把区间最小值与区间最大值这两个元素互换位置：
        // 最小值搬到最大值原来的位置，最大值搬到最小值原来的位置
        update(1, 1, n, rmnp, rmx);
        update(1, 1, n, rmxp, rmn);
        val[rmnp] = rmx;
        val[rmxp] = rmn;
    }

    for (int i = 1; i <= n; i++) {
        if (i > 1) cout << ' ';
        cout << val[i];
    }
    cout << '\n';
    return 0;
}
```

### 易错点

区间限定的是位置，最值比较的是值。先保存两个旧值再修改，避免第二次更新读到第一次写入后的值。

